CREATE OR REPLACE FUNCTION calculate_vpc(
    p_brake_wear NUMERIC,
    p_track_wear NUMERIC,
    p_speed NUMERIC,
    p_engine_load NUMERIC
) RETURNS NUMERIC AS $$
BEGIN
    IF p_brake_wear IS NULL OR p_track_wear IS NULL OR p_speed IS NULL OR p_engine_load IS NULL THEN
        RAISE EXCEPTION 'All inputs must be non-null';
    END IF;
    IF p_brake_wear < 0 OR p_brake_wear > 100 THEN
        RAISE EXCEPTION 'Brake pad wear percent must be between 0 and 100, got %', p_brake_wear;
    END IF;
    IF p_track_wear < 0 OR p_track_wear > 100 THEN
        RAISE EXCEPTION 'Track wear percent must be between 0 and 100, got %', p_track_wear;
    END IF;
    IF p_speed < 0 THEN
        RAISE EXCEPTION 'Vehicle speed must be non-negative, got %', p_speed;
    END IF;
    IF p_engine_load < 0 OR p_engine_load > 100 THEN
        RAISE EXCEPTION 'Engine load percent must be between 0 and 100, got %', p_engine_load;
    END IF;
    RETURN (1 - (p_brake_wear + p_track_wear) / 200.0) * (p_speed / 50.0) * (p_engine_load / 100.0);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_ewrii(p_equip_code TEXT)
RETURNS NUMERIC AS $$
DECLARE
    v_eff NUMERIC;
    v_source TEXT;
    v_esi NUMERIC;
    v_water_level NUMERIC;
    v_water_quality NUMERIC;
    v_waste_tank NUMERIC;
    v_wrmi NUMERIC;
    v_heater_temp NUMERIC;
BEGIN
    SELECT (pb.battery_telemetry->'power_state'->>'conversion_eff_pct')::NUMERIC,
           pb.battery_telemetry->'power_state'->>'primary_source'
      INTO v_eff, v_source
      FROM "PowerBattery" pb
     WHERE pb.equip_ref = p_equip_code
     LIMIT 1;

    SELECT w."waterLevelPct", w."waterQualityIdx", w."wasteTankPct"
      INTO v_water_level, v_water_quality, v_waste_tank
      FROM "WaterAndWaste" w
     WHERE w."equipRef" = p_equip_code
     LIMIT 1;

    SELECT (c.cabin_env_snapshot->'hvac'->>'heater_temp_c')::NUMERIC
      INTO v_heater_temp
      FROM "CabinEnvironment" c
     WHERE c."equipRef" = p_equip_code
     LIMIT 1;

    IF v_eff IS NULL OR v_water_level IS NULL OR v_water_quality IS NULL
       OR v_waste_tank IS NULL OR v_heater_temp IS NULL THEN
        RETURN 0;
    END IF;

    v_esi := v_eff * CASE
                         WHEN v_source IN ('Solar', 'Wind', 'Hybrid') THEN 1.5
                         WHEN v_source = 'Battery' THEN 1.0
                         WHEN v_source = 'Diesel' THEN 0.7
                         ELSE 0
                     END;

    v_wrmi := (v_water_level / 100) * (v_water_quality / 100) * (1 - v_waste_tank / 100);

    RETURN 0.5 * v_esi + 0.5 * v_wrmi * (1 - v_heater_temp / 100);
END;
$$ LANGUAGE plpgsql;

