CREATE OR REPLACE PROCEDURE award_hat_trick(p_driver_id INTEGER, p_race_id INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_is_pole BOOLEAN;
    v_is_winner BOOLEAN;
    v_has_fastest_lap BOOLEAN;
BEGIN
    -- Pole Position: 1st in qualifying
    SELECT EXISTS (
        SELECT 1 FROM qualifying
        WHERE rbind = p_race_id AND pilotrec = p_driver_id AND px_pos = 1
    ) INTO v_is_pole;

    -- Race Winner: classified 1st on the final lap of the race
    SELECT EXISTS (
        SELECT 1 FROM lap_times
        WHERE rc_index = p_race_id AND wheel_unit = p_driver_id AND pp = 1
          AND lapval = (SELECT MAX(lapval) FROM lap_times WHERE rc_index = p_race_id)
    ) INTO v_is_winner;

    -- Fastest Lap Award: single quickest lap of the race (points finish implied by the win)
    SELECT EXISTS (
        SELECT 1 FROM lap_times
        WHERE rc_index = p_race_id AND wheel_unit = p_driver_id
          AND msec_val = (SELECT MIN(msec_val) FROM lap_times WHERE rc_index = p_race_id)
    ) INTO v_has_fastest_lap;

    IF v_is_pole AND v_is_winner AND v_has_fastest_lap THEN
        INSERT INTO achievements (driver_id, race_id, achievement_type)
        VALUES (p_driver_id, p_race_id, 'Hat Trick');
    END IF;
END;
$$;

