CREATE OR REPLACE FUNCTION calculate_wdr(
    offered_wage NUMERIC,
    prevailing_wage NUMERIC,
    offered_unit TEXT,
    prevailing_unit TEXT
) RETURNS NUMERIC AS $$
DECLARE
    offered_annual NUMERIC;
    prevailing_annual NUMERIC;
BEGIN
    IF prevailing_wage IS NULL OR prevailing_wage = 0 OR offered_wage IS NULL THEN
        RETURN NULL;
    END IF;

    offered_annual := offered_wage * CASE offered_unit
        WHEN 'Hour' THEN 2080
        WHEN 'Week' THEN 52
        WHEN 'Month' THEN 12
        WHEN 'Year' THEN 1
        ELSE 1 END;

    prevailing_annual := prevailing_wage * CASE prevailing_unit
        WHEN 'Hour' THEN 2080
        WHEN 'Week' THEN 52
        WHEN 'Month' THEN 12
        WHEN 'Year' THEN 1
        ELSE 1 END;

    RETURN ROUND(((offered_annual - prevailing_annual) / prevailing_annual) * 100, 2);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION fn_classify_wage_competitiveness()
RETURNS TRIGGER AS $$
DECLARE
    v_offered      NUMERIC;
    v_prevailing   NUMERIC;
    v_offered_unit TEXT;
    v_pw_unit      TEXT;
    v_offered_ann  NUMERIC;
    v_pw_ann       NUMERIC;
    v_wdr          NUMERIC;
    v_tier         TEXT;
BEGIN
    IF NEW.wage_details IS NULL THEN
        RETURN NEW;
    END IF;

    v_offered := NULLIF(regexp_replace(NEW.wage_details->'offered_wage'->>'from', '[^0-9.]', '', 'g'), '')::NUMERIC;
    v_prevailing := NULLIF(regexp_replace(NEW.wage_details->'prevailing_wage'->>'value', '[^0-9.]', '', 'g'), '')::NUMERIC;
    v_offered_unit := NEW.wage_details->'offered_wage'->>'unit';
    v_pw_unit := NEW.wage_details->'prevailing_wage'->>'unit';

    -- Convert both wages to an annual basis
    v_offered_ann := v_offered * CASE v_offered_unit
                        WHEN 'Hour' THEN 2080 WHEN 'Week' THEN 52
                        WHEN 'Month' THEN 12 WHEN 'Year' THEN 1 END;
    v_pw_ann := v_prevailing * CASE v_pw_unit
                        WHEN 'Hour' THEN 2080 WHEN 'Week' THEN 52
                        WHEN 'Month' THEN 12 WHEN 'Year' THEN 1 END;

    IF v_offered_ann IS NULL OR v_pw_ann IS NULL OR v_pw_ann = 0 THEN
        NEW.wage_details := NEW.wage_details - 'wage_analysis';
        RETURN NEW;
    END IF;

    -- Wage Differential Rate
    v_wdr := ROUND(((v_offered_ann - v_pw_ann) / v_pw_ann) * 100, 2);

    -- Wage Competitiveness Tiers
    v_tier := CASE
                WHEN v_wdr < 0 THEN 'Below-Market'
                WHEN v_wdr <= 10 THEN 'Market-Competitive'
                ELSE 'Premium'
              END;

    NEW.wage_details := NEW.wage_details || jsonb_build_object(
        'wage_analysis', jsonb_build_object(
            'annualized_offered_wage', ROUND(v_offered_ann, 2),
            'annualized_prevailing_wage', ROUND(v_pw_ann, 2),
            'wdr_pct', v_wdr,
            'competitiveness_tier', v_tier
        )
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_classify_wage_competitiveness
