FOR EACH ROW
EXECUTE FUNCTION fn_classify_wage_competitiveness();

CREATE OR REPLACE FUNCTION get_visa_filing_window(p_receipt_date TEXT, p_start_date TEXT)
RETURNS TEXT AS $$
DECLARE
    v_receipt DATE;
    v_start   DATE;
    v_months  INTEGER;
BEGIN
    IF p_receipt_date IS NULL OR p_start_date IS NULL
       OR btrim(p_receipt_date) = '' OR btrim(p_start_date) = '' THEN
        RETURN NULL;
    END IF;

    -- receipt date: YYYY/MM/DD (or YYYY-MM-DD), otherwise DD/MM/YYYY
    IF btrim(p_receipt_date) ~ '^\d{4}[/-]\d{1,2}[/-]\d{1,2}$' THEN
        v_receipt := TO_DATE(replace(btrim(p_receipt_date), '-', '/'), 'YYYY/MM/DD');
    ELSE
        v_receipt := TO_DATE(replace(btrim(p_receipt_date), '-', '/'), 'DD/MM/YYYY');
    END IF;

    -- start date: DD/MM/YYYY (or YYYY/MM/DD / YYYY-MM-DD)
    IF btrim(p_start_date) ~ '^\d{4}[/-]\d{1,2}[/-]\d{1,2}$' THEN
        v_start := TO_DATE(replace(btrim(p_start_date), '-', '/'), 'YYYY/MM/DD');
    ELSE
        v_start := TO_DATE(replace(btrim(p_start_date), '-', '/'), 'DD/MM/YYYY');
    END IF;

    v_months := (EXTRACT(YEAR FROM v_start) - EXTRACT(YEAR FROM v_receipt)) * 12
              + (EXTRACT(MONTH FROM v_start) - EXTRACT(MONTH FROM v_receipt));

    RETURN CASE
        WHEN v_months BETWEEN 4 AND 6 THEN 'Optimal Window (4-6 Months)'
        WHEN v_months > 6             THEN 'Early Filing'
        WHEN v_months BETWEEN 1 AND 3 THEN '1-3 Months Before'
        WHEN v_months = 0             THEN 'Same Month'
        ELSE 'After Start Date'
    END;
END;
$$ LANGUAGE plpgsql;

