CREATE OR REPLACE FUNCTION calculate_size_compatibility(p_donor_id TEXT, p_recipient_id TEXT)
RETURNS NUMERIC AS $$
DECLARE
    v_donor_bmi NUMERIC;
    v_recip_bmi NUMERIC;
BEGIN
    SELECT (d.physicalstats->>'Bmi_Value')::NUMERIC INTO v_donor_bmi
    FROM demographics d
    WHERE d.contrib_registry = p_donor_id;

    SELECT r.bmi_val::NUMERIC INTO v_recip_bmi
    FROM recipients_demographics r
    WHERE r.recip_registry = p_recipient_id;

    IF v_donor_bmi IS NULL OR v_recip_bmi IS NULL OR v_recip_bmi = 0 THEN
        RETURN NULL;
    END IF;

    RETURN 1 - ABS(v_donor_bmi / v_recip_bmi - 1);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_donor_renal_score(p_donor_id text)
RETURNS numeric
LANGUAGE plpgsql
AS $$
DECLARE
    v_cr   numeric;
    v_age  numeric;
    v_egfr numeric;
BEGIN
    SELECT substring(f.don_crtn_val FROM '([0-9]+\.?[0-9]*)')::numeric,
           substring(d.age_count FROM '([0-9]+)')::numeric
      INTO v_cr, v_age
      FROM function_and_recovery f
      JOIN demographics d ON d.contrib_registry = f.recov_don_registry
     WHERE f.recov_don_registry = p_donor_id;

    IF v_cr IS NULL OR v_cr <= 0 OR v_age IS NULL THEN
        RETURN NULL;
    END IF;

    -- eGFR = 141 * (Cr/0.9)^-0.411 * 0.993^Age
    v_egfr := 141 * power(v_cr / 0.9, -0.411) * power(0.993, v_age);

    -- Renal Function Score with weights 0.8 (eGFR) and 0.2 (creatinine)
    RETURN (0.8 * v_egfr) - (0.2 * v_cr);
END;
$$;

