CREATE OR REPLACE FUNCTION fn_update_center_performance() RETURNS trigger AS $$
DECLARE
    v_center text;
    v_egs real;
BEGIN
    IF NEW.match_status = 'Completed'
       AND (TG_OP = 'INSERT' OR OLD.match_status IS DISTINCT FROM 'Completed') THEN
        SELECT a.tx_cen_code INTO v_center
        FROM administrative_and_review a
        WHERE a.adm_rev_registry = NEW.match_rec_registry;

        IF v_center IS NULL THEN
            RETURN NEW;
        END IF;

        SELECT r.egs_val INTO v_egs
        FROM risk_evaluation r
        WHERE r.risk_eval_registry = NEW.match_rec_registry;

        UPDATE center_performance_live c
        SET avg_egs_score = CASE
                WHEN v_egs IS NULL THEN c.avg_egs_score
                WHEN c.avg_egs_score IS NULL THEN v_egs
                ELSE (c.avg_egs_score * c.total_transplants + v_egs) / (c.total_transplants + 1)
            END,
            total_transplants = c.total_transplants + 1
        WHERE c.center_id = v_center;

        IF NOT FOUND THEN
            INSERT INTO center_performance_live (center_id, total_transplants, avg_egs_score)
            VALUES (v_center, 1, v_egs);
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

