CREATE OR REPLACE FUNCTION calculate_composite_allocation_score(p_match_id TEXT)
RETURNS DOUBLE PRECISION
LANGUAGE plpgsql
AS $$
DECLARE
    v_status_medical DOUBLE PRECISION;
    v_wait_days      DOUBLE PRECISION;
    v_i_abo          DOUBLE PRECISION;
    v_hla_mismatch   DOUBLE PRECISION;
    v_donor_age      DOUBLE PRECISION;
    v_r_wait         DOUBLE PRECISION;
    v_s_urgency      DOUBLE PRECISION;
    v_s_immune       DOUBLE PRECISION;
    v_egs            DOUBLE PRECISION;
BEGIN
    SELECT
        CASE
            WHEN upper(trim(c.med_urgency)) IN ('STATUS 1A', '1A') THEN 5
            WHEN upper(trim(c.med_urgency)) IN ('STATUS 1B', '1B') THEN 4
            WHEN upper(trim(c.med_urgency)) IN ('STATUS 2', '2')   THEN 3
            WHEN upper(trim(c.med_urgency)) IN ('STATUS 3', '3')   THEN 2
            ELSE 1
        END,
        substring(c.wait_time FROM '(\d+(?:\.\d+)?)')::DOUBLE PRECISION,
        CASE WHEN lower(trim(cm.blood_compat)) = 'compatible' THEN 1 ELSE 0 END,
        cm.hla_mis_count::DOUBLE PRECISION,
        substring(d.age_count FROM '(\d+(?:\.\d+)?)')::DOUBLE PRECISION
    INTO v_status_medical, v_wait_days, v_i_abo, v_hla_mismatch, v_donor_age
    FROM transplant_matching tm
    LEFT JOIN clinical c               ON c.clin_recip_registry = tm.recip_ref_reg
    LEFT JOIN compatibility_metrics cm ON cm.match_comp_registry = tm.match_rec_registry
    LEFT JOIN demographics d           ON d.contrib_registry = tm.donor_ref_reg
    WHERE tm.match_rec_registry = p_match_id;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- Recipient Wait Time Ratio
    v_r_wait := v_wait_days / 365.0;
    -- Patient Urgency Score
    v_s_urgency := 0.7 * v_status_medical + 0.3 * v_r_wait;
    -- Immunological Compatibility Score
    v_s_immune := 0.6 * v_i_abo + 0.4 * (1 - v_hla_mismatch / 6.0);
    -- Expected Graft Survival (EGS) Score
    v_egs := 1.0 / (1.0 + exp(-(-0.5 + 1.5 * v_s_immune - 0.02 * v_donor_age)));

    -- Composite Allocation Score
    RETURN 0.5 * v_s_urgency + 0.25 * v_s_immune + 0.25 * v_egs;
END;
$$;

CREATE OR REPLACE FUNCTION calculate_tes(p_tx_key BIGINT)
RETURNS NUMERIC AS $$
DECLARE
    v_eng TEXT;
BEGIN
    SELECT th_eng INTO v_eng FROM treatmentbasics WHERE tx_key = p_tx_key;
    RETURN CASE v_eng
        WHEN 'High' THEN 3
        WHEN 'Medium' THEN 2
        WHEN 'Low' THEN 1
        ELSE NULL
    END;
END;
$$ LANGUAGE plpgsql;

