CREATE OR REPLACE FUNCTION get_appraisal_ratio(p_ticker VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_alpha     DOUBLE PRECISION;
    v_vol       DOUBLE PRECISION;
    v_rsq       DOUBLE PRECISION;
    v_unsys     DOUBLE PRECISION;
BEGIN
    IF p_ticker IS NULL OR TRIM(p_ticker) = '' THEN
        RETURN NULL;
    END IF;

    SELECT alpha3y, volatility3y, rsquared3y
      INTO v_alpha, v_vol, v_rsq
      FROM risk_metrics
     WHERE UPPER(TRIM(investmentref)) = UPPER(TRIM(p_ticker))
     LIMIT 1;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- missing or invalid (NaN) inputs
    IF v_alpha IS NULL OR v_vol IS NULL OR v_rsq IS NULL
       OR v_alpha = 'NaN'::float8 OR v_vol = 'NaN'::float8 OR v_rsq = 'NaN'::float8 THEN
        RETURN NULL;
    END IF;

    -- R-squared is stored as a percentage (0-100); convert to a fraction
    v_rsq := v_rsq / 100.0;

    IF v_vol <= 0 OR v_rsq < 0 OR v_rsq >= 1 THEN
        RETURN NULL;
    END IF;

    -- Unsystematic Risk = 3Y Volatility * sqrt(1 - 3Y R-Squared)
    v_unsys := v_vol * SQRT(1 - v_rsq);

    IF v_unsys = 0 THEN
        RETURN NULL;
    END IF;

    -- Appraisal Ratio = 3Y Alpha / Unsystematic Risk
    RETURN (v_alpha / v_unsys)::NUMERIC;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE IF NOT EXISTS annual_returns_archive (LIKE annual_returns);

CREATE OR REPLACE PROCEDURE archive_old_returns(p_years_to_keep INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_cutoff_year BIGINT := EXTRACT(YEAR FROM CURRENT_DATE)::BIGINT - p_years_to_keep;
BEGIN
    INSERT INTO annual_returns_archive
    SELECT * FROM annual_returns WHERE calendaryear < v_cutoff_year;

    DELETE FROM annual_returns WHERE calendaryear < v_cutoff_year;
END;
$$;

CALL archive_old_returns(10);

CREATE TABLE IF NOT EXISTS style_drift_log (
    log_id SERIAL PRIMARY KEY,
    investmentref VARCHAR,
    old_beta3y REAL,
    new_beta3y REAL,
    old_rsquared3y REAL,
    new_rsquared3y REAL,
    drift_detected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE OR REPLACE FUNCTION log_style_drift() RETURNS TRIGGER AS $$
BEGIN
    IF ABS(NEW.beta3y - OLD.beta3y) > 0.15
       OR ABS(NEW.rsquared3y - OLD.rsquared3y) > 10 THEN
        INSERT INTO style_drift_log (investmentref, old_beta3y, new_beta3y, old_rsquared3y, new_rsquared3y, drift_detected_at)
        VALUES (NEW.investmentref, OLD.beta3y, NEW.beta3y, OLD.rsquared3y, NEW.rsquared3y, CURRENT_TIMESTAMP);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_log_style_drift
AFTER UPDATE ON risk_metrics
FOR EACH ROW EXECUTE FUNCTION log_style_drift();

ALTER TABLE funds ADD COLUMN IF NOT EXISTS rrei_score NUMERIC;

CREATE OR REPLACE FUNCTION calculate_rrei(p_ticker VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
  v_r1y NUMERIC; v_exp NUMERIC; v_vol NUMERIC;
BEGIN
  SELECT p.r1y, f.expensenet, rm.volatility3y
    INTO v_r1y, v_exp, v_vol
  FROM funds f
  JOIN performance p ON p.productref = f.tickersym
  JOIN risk_metrics rm ON rm.investmentref = f.tickersym
  WHERE f.tickersym = p_ticker;
  IF v_r1y IS NULL OR v_exp IS NULL OR v_vol IS NULL OR v_exp = 0 OR v_vol = 0 THEN
    RETURN NULL;
  END IF;
  RETURN (v_r1y / v_exp) / v_vol;
END;
$$ LANGUAGE plpgsql;

UPDATE funds SET rrei_score = calculate_rrei(tickersym);

CREATE OR REPLACE FUNCTION calculate_adc(p_transport_id VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
    v_total_cost NUMERIC;
    v_total_tons NUMERIC;
BEGIN
    SELECT SUM(f.transportcostsusd),
           MAX((t.delivery_metrics->'delivery_capacity'->>'total_tons')::NUMERIC)
      INTO v_total_cost, v_total_tons
      FROM transportation t
      LEFT JOIN financials f ON f.findistref = t.transportdistref
     WHERE t.transportregistry = p_transport_id;

    IF v_total_tons IS NULL OR v_total_tons = 0 THEN
        RAISE EXCEPTION 'Total tons delivered is zero or NULL for transport ID %', p_transport_id;
    END IF;

    RETURN v_total_cost / v_total_tons;
END;
$$ LANGUAGE plpgsql;

