CREATE OR REPLACE FUNCTION calculate_cpi(
    p_hist_significance NUMERIC,
    p_research_score NUMERIC,
    p_cultural_score NUMERIC,
    p_conserve_status TEXT
) RETURNS NUMERIC AS $$
DECLARE
    v_status_value NUMERIC;
BEGIN
    v_status_value := CASE p_conserve_status
        WHEN 'Excellent' THEN 1
        WHEN 'Good' THEN 3
        WHEN 'Fair' THEN 5
        WHEN 'Poor' THEN 7
        WHEN 'Critical' THEN 10
        ELSE NULL
    END;
    RETURN ((p_hist_significance + p_research_score + p_cultural_score) * (10 - v_status_value)) / 30.0;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION pct_to_numeric(pct_text text)
RETURNS numeric AS $$
BEGIN
    RETURN (NULLIF(TRIM(REPLACE(pct_text, '%', '')), ''))::numeric / 100;
END;
$$ LANGUAGE plpgsql IMMUTABLE;
